import { NextResponse } from 'next/server'

type PostContext = { params: Promise<{ id: string }> }
type PostInput = { title?: string; content?: string }

export async function GET(_request: Request, { params }: PostContext) {
  const { id } = await params
  return NextResponse.json({
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, { params }: PostContext) {
  const { id } = await params
