import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { NavigationButton } from '../../../components/NavigationButton'
import { getComments, getPost, getPosts } from '../../../lib/posts'

type BlogPostProps = { params: Promise<{ id: string }> }

export const revalidate = 300

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts = await getPosts(300)
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

export async function generateMetadata({ params }: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  if (!/^\d+$/.test(id)) return {}
  const post = await getPost(id)
  if (!post) return {}
  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: { title: post.title, description: post.body.substring(0, 160) },
  }
}

export default async function BlogPost({ params }: BlogPostProps) {
  const { id } = await params
  if (!/^\d+$/.test(id)) notFound()
  const post = await getPost(id)
  if (!post) notFound()
  const comments = await getComments(id)

  return (
    <article>
      <NavigationButton back>← Back</NavigationButton>
      <h1>{post.title}</h1>
      <p>{post.body}</p>
      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

